mapper.select:
SELECT u.user_id, u.nickname, u.status, u.create_time, a.auth_type, a.identifier, i.gender, i.phone, i.city FROM sys_user u LEFT JOIN user_auth a ON u.user_id = a.user_id LEFT JOIN user_info i ON u.user_id = i.user_id
LEFT JOIN sys_user_role ur ON u.user_id = ur.user_id
u.del_flag = 0
AND a.auth_type = #{query.authType}
AND a.identifier LIKE CONCAT('%', #{query.identifier}, '%')
AND i.gender = #{query.gender}
AND i.phone LIKE CONCAT('%', #{query.phone}, '%')
AND i.city = #{query.city}
AND ur.role_id = #{query.roleId}
AND u.status = #{query.status}
AND u.create_time >= #{query.startTime}
AND u.create_time <= #{query.endTime}
ORDER BY u.create_time DESC
